  "ch7.hex.aria": "The 92 bytes of the primary GPT header, in hex",
  "ch7.read.crc": "Recomputed header CRC32 (red: does not match the stored one)",
  "ch7.read.arr": "Recomputed partition entry CRC32 (red: mismatch)",
  "ch7.read.use": "Which copy the firmware uses",
  "ch7.read.esp": "EFI system partition found",
